
'use strict';
// Multi-page document state. Images are encoded once; undo keeps only editable metadata.
const studio={pages:[],active:-1,selection:new Set(),crop:null,autoNumber:true,revision:0,busy:false,restoring:false};
const base={update,drawObject,bounds,syncSelected,validateProject,projectData,setTool};
const zeroMargins=()=>({top:0,bottom:0,left:0,right:0});
const clone=value=>structuredClone(value);
const uid=()=>crypto.randomUUID();
const typeLabels={rect:'紅框',arrow:'箭頭',number:'編號',text:'文字',mosaic:'馬賽克',mask:'實心遮蔽',step:'步驟',highlight:'螢光筆',spotlight:'聚光燈',magnify:'局部放大'};
Object.assign(hints,{highlight:'拖曳畫出半透明螢光標記。',spotlight:'拖曳保留清晰的重點區，其他區域會變暗。',magnify:'拖曳框選要放大的原圖區域，再移動產生的放大框。',crop:'拖曳裁切原圖區域；裁切可復原，也可還原原圖。'});
function encodeImage(img){if(img.dataset?.encoded)return img.dataset.encoded;const c=document.createElement('canvas');c.width=img.width;c.height=img.height;c.getContext('2d').drawImage(img,0,0);return c.toDataURL('image/png')}
function currentPage(){return studio.pages[studio.active]}
function capturePage(){const p=currentPage();if(!p||!sourceImage)return;p.items=items;p.margins={...margins};p.crop=studio.crop?{...studio.crop}:null;p.history=history;p.historyIndex=historyIndex;p.nextNumber=Number($('nextNumber').value)||1;p.name=filename}
function croppedBase(src,crop){if(!crop)return src;const c=document.createElement('canvas');c.width=crop.w;c.height=crop.h;c.getContext('2d').drawImage(src,crop.x,crop.y,crop.w,crop.h,0,0,crop.w,crop.h);return c}
function rebuildImage(){image=paddedImage(croppedBase(sourceImage,studio.crop),margins);canvas.width=image.width;canvas.height=image.height;$('dimensions').textContent=image.width+' × '+image.height+' px'}
snapshot=()=>JSON.stringify({items,margins,crop:studio.crop});
restore=function(state){const data=JSON.parse(state);items=data.items;margins=data.margins;studio.crop=data.crop||null;selected=-1;studio.selection.clear();rebuildImage();syncMargins();setZoom(zoom);capturePage();studio.revision++;scheduleDraft()};
function renumber(){if(!studio.autoNumber)return;let n=1;items.forEach(o=>{if(o.type==='step'||o.type==='number')o.n=n++});$('nextNumber').value=Math.min(999,n)}
commit=function(){if(!image)return;items.forEach(o=>{if(!o.id)o.id=uid()});renumber();const state=snapshot();if(history[historyIndex]!==state){history=history.slice(0,historyIndex+1);history.push(state);if(history.length>80)history.shift();historyIndex=history.length-1}studio.revision++;capturePage();update();render();scheduleDraft()};
undo=function(){if(historyIndex>0){restore(history[--historyIndex]);renumber();update();render()}};
redo=function(){if(historyIndex<history.length-1){restore(history[++historyIndex]);renumber();update();render()}};
$('undo').onclick=undo;$('redo').onclick=redo;
function setSelection(indices){studio.selection=new Set(indices.filter(i=>i>=0&&i<items.length));selected=[...studio.selection].at(-1)??-1;if(selected>=0)syncSelected();else update();render()}
setTool=function(value){studio.selection.clear();base.setTool(value)};
syncSelected=function(){base.syncSelected();const o=items[selected];$('magnifyScale').value=o?.factor||2;const locked=!!o?.locked;for(const id of ['textInput','width','size','color','stepNumber','stepWidth'])$(id).disabled=locked};
update=function(){base.update();for(const id of ['textInput','width','size','color','stepWidth'])$(id).disabled=!!items[selected]?.locked;if(selected>=0&&!studio.selection.size)studio.selection.add(selected);for(const i of [...studio.selection])if(i>=items.length)studio.selection.delete(i);const ready=!!image;for(const id of ['exportBook','duplicate','lockItems','selectAll','clearSelection','alignItems','applyTemplate','applyPreset','resetCrop','ocrOpen','replacePage','deletePage'])$(id).disabled=!ready;const ids=[...studio.selection];$('duplicate').disabled=!ids.length;$('lockItems').disabled=!ids.length;$('delete').disabled=!ids.some(i=>!items[i]?.locked);$('alignItems').disabled=ids.filter(i=>!items[i]?.locked).length<2;$('pageUp').disabled=studio.active<=0;$('pageDown').disabled=studio.active<0||studio.active===studio.pages.length-1;$('pageTitle').disabled=!ready;$('autoNumber').checked=studio.autoNumber;$('stepNumber').disabled=studio.autoNumber||!!items[selected]?.locked;$('count').textContent=items.length+' 個標註'+(ids.length>1?' · 選取 '+ids.length+' 個':'');renderPages();renderObjects()};
function makePage(img,name){const p={id:uid(),source:img,encoded:encodeImage(img),name:name.replace(/\.[^.]+$/,'')||'教學截圖',title:name.replace(/\.[^.]+$/,''),items:[],margins:zeroMargins(),crop:null,nextNumber:1,history:[],historyIndex:0};p.history=[JSON.stringify({items:[],margins:p.margins,crop:null})];return p}
function activatePage(index,save=true){if(index<0||index>=studio.pages.length)return;if(save)capturePage();const p=studio.pages[index];studio.active=index;sourceImage=p.source;filename=p.name;items=p.items;margins={...p.margins};studio.crop=p.crop?{...p.crop}:null;history=p.history;historyIndex=p.historyIndex;selected=-1;studio.selection.clear();drag=null;$('nextNumber').value=p.nextNumber;$('pageTitle').value=p.title;$('filename').textContent=p.title||p.name;$('empty').hidden=true;$('canvasWrap').hidden=false;rebuildImage();syncMargins();for(const id of ['textInput','width','size','color','stepNumber','stepWidth'])$(id).disabled=false;fit();update();render()}
acceptImage=function(img,name){if(studio.pages.length&&!confirm('開啟新圖片會取代整份教學。請先儲存專案；若要保留其他頁，請使用「新增頁面」。'))return false;studio.pages=[makePage(img,name)];studio.active=-1;activatePage(0,false);setTool('rect');studio.revision++;scheduleDraft();toast('圖片已開啟，可標註或新增更多頁面');return true};
function renderPages(){const strip=$('pageStrip');strip.replaceChildren();studio.pages.forEach((p,i)=>{const b=document.createElement('button');b.textContent=(i+1)+'. '+(p.title||'未命名');b.classList.toggle('current',i===studio.active);b.setAttribute('aria-current',i===studio.active?'page':'false');b.onclick=()=>{activatePage(i);scheduleDraft()};strip.append(b)});if(!studio.pages.length)strip.textContent='新增截圖，建立可逐頁編輯的教學。'}
function renderObjects(){const list=$('objectList');list.replaceChildren();items.forEach((o,i)=>{const row=document.createElement('li');row.classList.toggle('selected',studio.selection.has(i));const name=document.createElement('button');name.className='object-name';name.textContent=(o.locked?'🔒 ':'')+(o.n?o.n+'. ':'')+(o.text||typeLabels[o.type]||o.type);name.onclick=e=>{if(e.shiftKey){const next=new Set(studio.selection);next.has(i)?next.delete(i):next.add(i);setSelection([...next])}else setSelection([i]);tool='select';document.querySelectorAll('[data-tool]').forEach(b=>{b.classList.toggle('active',b.dataset.tool==='select');b.setAttribute('aria-pressed',String(b.dataset.tool==='select'))})};const actions=document.createElement('div');actions.className='row-actions';for(const [label,action]of [['前移',()=>moveObject(i,-1)],['後移',()=>moveObject(i,1)],[o.locked?'解鎖':'鎖定',()=>{o.locked=!o.locked;commit()}]]){const b=document.createElement('button');b.textContent=label;b.disabled=(label==='前移'&&i===0)||(label==='後移'&&i===items.length-1);b.onclick=action;actions.append(b)}row.draggable=true;row.ondragstart=e=>e.dataTransfer.setData('text/x-studio-object',String(i));row.ondragover=e=>e.preventDefault();row.ondrop=e=>{e.preventDefault();const raw=e.dataTransfer.getData('text/x-studio-object');if(raw==='')return;const from=Number(raw);if(Number.isInteger(from)&&from>=0&&from<items.length){const [o]=items.splice(from,1);items.splice(i,0,o);setSelection([i]);commit()}};row.append(name,actions);list.append(row)})}
function moveObject(i,delta){const j=i+delta;if(j<0||j>=items.length)return;[items[i],items[j]]=[items[j],items[i]];setSelection([j]);commit()}
function movePage(delta){const i=studio.active,j=i+delta;if(j<0||j>=studio.pages.length)return;capturePage();[studio.pages[i],studio.pages[j]]=[studio.pages[j],studio.pages[i]];activatePage(j,false);studio.revision++;scheduleDraft()}
$('pageUp').onclick=()=>movePage(-1);$('pageDown').onclick=()=>movePage(1);
$('pageTitle').oninput=()=>{if(currentPage()){currentPage().title=$('pageTitle').value;$('filename').textContent=currentPage().title;renderPages();scheduleDraft()}};
$('deletePage').onclick=()=>{if(!currentPage()||!confirm('刪除此頁？其他頁面會保留；刪頁後無法用標註復原恢復。'))return;studio.pages.splice(studio.active,1);if(studio.pages.length)activatePage(Math.min(studio.active,studio.pages.length-1),false);else{studio.active=-1;sourceImage=image=null;items=[];selected=-1;studio.selection.clear();history=['[]'];historyIndex=0;$('empty').hidden=false;$('canvasWrap').hidden=true;$('pageTitle').value='';$('filename').textContent='尚未開啟圖片';update()}studio.revision++;scheduleDraft()};
$('autoNumber').onchange=()=>{studio.autoNumber=$('autoNumber').checked;commit()};
async function decodeFile(file){if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)||file.size>30*1024*1024)throw Error('請選擇 30 MB 以下的 PNG、JPG、WebP 或 GIF');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(img.width>16000||img.height>16000||img.width*img.height>32000000)throw Error('圖片尺寸過大');return img}finally{URL.revokeObjectURL(url)}}
let pageFileMode='add';
$('addPages').onclick=()=>{pageFileMode='add';$('pageFiles').multiple=true;$('pageFiles').click()};
$('replacePage').onclick=()=>{pageFileMode='replace';$('pageFiles').multiple=false;$('pageFiles').click()};
$('pageFiles').onchange=async e=>{const files=[...e.target.files];e.target.value='';if(!files.length)return;try{if(studio.pages.length+files.length>30&&pageFileMode==='add')throw Error('一份教學最多 30 頁');const loaded=[];let pixels=pageFileMode==='replace'?0:studio.pages.reduce((n,p)=>n+p.source.width*p.source.height,0);for(const f of files){const img=await decodeFile(f);pixels+=img.width*img.height;if(pixels>100000000)throw Error('圖片總尺寸過大，請減少頁數');loaded.push(makePage(img,f.name))}capturePage();if(pageFileMode==='replace'&&currentPage()){if(!confirm('替換本頁圖片會清除此頁標註與裁切，其他頁不變。'))return;loaded[0].title=currentPage().title;studio.pages[studio.active]=loaded[0];activatePage(studio.active,false)}else{studio.pages.push(...loaded);activatePage(studio.pages.length-loaded.length,false)}studio.revision++;scheduleDraft();toast('頁面已加入，每頁可分別編輯')}catch(e){toast(e.message)}};
$('buildMerge').onclick=()=>{if(mergeBusy||mergeImages.length<2)return;try{if(studio.pages.length+mergeImages.length>30)throw Error('一份教學最多 30 頁');if(studio.pages.reduce((n,p)=>n+p.source.width*p.source.height,0)+mergeImages.reduce((n,p)=>n+p.img.width*p.img.height,0)>100000000)throw Error('圖片總尺寸過大');const added=mergeImages.map(o=>makePage(o.img,o.name));capturePage();const start=studio.pages.length;studio.pages.push(...added);activatePage(start,false);$('mergeDialog').close();studio.revision++;scheduleDraft();toast('已加入獨立頁面，可用「匯出整份教學」製作長圖或 PDF')}catch(e){toast(e.message)}};


let cropPreview=null;
function safeOriginal(){const c=document.createElement('canvas');c.width=image.width;c.height=image.height;const g=c.getContext('2d');g.drawImage(image,0,0);items.filter(o=>o.type==='mosaic'||o.type==='mask').sort((a,b)=>(a.type==='mask')-(b.type==='mask')).forEach(o=>base.drawObject(g,o));return c}
drawObject=function(c,o){if(o.type==='highlight'){const b=bounds(o);c.save();c.globalAlpha=.32;c.fillStyle=o.color;c.fillRect(b.x,b.y,b.w,b.h);c.restore();return}if(o.type==='spotlight')return;if(o.type==='magnify'){const b=bounds(o),safe=safeOriginal();c.save();c.strokeStyle=o.color;c.lineWidth=o.width;c.setLineDash([8,6]);c.strokeRect(o.sx,o.sy,o.sw,o.sh);c.beginPath();c.moveTo(o.sx+o.sw/2,o.sy+o.sh/2);c.lineTo(b.x+b.w/2,b.y+b.h/2);c.stroke();c.setLineDash([]);c.fillStyle='#fff';c.fillRect(b.x,b.y,b.w,b.h);c.drawImage(safe,o.sx,o.sy,o.sw,o.sh,b.x,b.y,b.w,b.h);c.strokeRect(b.x,b.y,b.w,b.h);c.restore();return}base.drawObject(c,o)};
paintAnnotations=function(c){const spots=items.filter(o=>o.type==='spotlight');if(spots.length){const shade=document.createElement('canvas');shade.width=image.width;shade.height=image.height;const g=shade.getContext('2d');g.fillStyle='rgba(10,18,32,.58)';g.fillRect(0,0,shade.width,shade.height);spots.forEach(o=>{const b=bounds(o);g.clearRect(b.x,b.y,b.w,b.h)});c.drawImage(shade,0,0)}items.filter(o=>o.type!=='mask'&&o.type!=='spotlight').forEach(o=>drawObject(c,o));items.filter(o=>o.type==='mask').forEach(o=>drawObject(c,o))};
render=function(){if(!image)return;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0);paintAnnotations(ctx);const ids=new Set(studio.selection);if(selected>=0)ids.add(selected);for(const i of ids){if(!items[i])continue;const o=items[i],b=bounds(o),p=5/zoom;ctx.save();ctx.strokeStyle=o.locked?'#64748b':'#2563eb';ctx.lineWidth=1.5/zoom;ctx.setLineDash([5/zoom,4/zoom]);ctx.strokeRect(b.x-p,b.y-p,b.w+2*p,b.h+2*p);if(ids.size===1&&!o.locked){ctx.setLineDash([]);ctx.fillStyle='#fff';ctx.fillRect(b.x+b.w-5/zoom,b.y+b.h-5/zoom,10/zoom,10/zoom);ctx.strokeRect(b.x+b.w-5/zoom,b.y+b.h-5/zoom,10/zoom,10/zoom)}ctx.restore()}if(cropPreview){ctx.save();ctx.strokeStyle='#2563eb';ctx.lineWidth=2/zoom;ctx.setLineDash([8/zoom,4/zoom]);ctx.strokeRect(cropPreview.x,cropPreview.y,cropPreview.w,cropPreview.h);ctx.restore()}};
function shiftObjects(dx,dy){items.forEach(o=>{o.x+=dx;o.y+=dy;if(o.type==='magnify'){o.sx+=dx;o.sy+=dy}})}
function applyCanvasMargins(next,save=true){const prepared=paddedImage(croppedBase(sourceImage,studio.crop),next);shiftObjects(next.left-margins.left,next.top-margins.top);margins=next;image=prepared;canvas.width=image.width;canvas.height=image.height;syncMargins();selected=-1;studio.selection.clear();$('dimensions').textContent=image.width+' × '+image.height+' px';if(save)commit();fit()}
$('applyMargins').onclick=()=>{if(!image)return;try{const m={};for(const side of ['top','bottom','left','right']){const n=Number($('margin'+side[0].toUpperCase()+side.slice(1)).value);if(!Number.isInteger(n)||n<0||n>2000)throw Error('留白需為 0–2000 整數');m[side]=n}applyCanvasMargins(m)}catch(e){toast(e.message)}};
function applyCrop(rect){const previous=studio.crop||{x:0,y:0,w:sourceImage.width,h:sourceImage.height};const x0=Math.max(0,Math.min(previous.w,rect.x-margins.left)),y0=Math.max(0,Math.min(previous.h,rect.y-margins.top)),x1=Math.max(0,Math.min(previous.w,rect.x+rect.w-margins.left)),y1=Math.max(0,Math.min(previous.h,rect.y+rect.h-margins.top));if(x1-x0<4||y1-y0<4){toast('請在原圖範圍內框選裁切區域');return}studio.crop={x:Math.floor(previous.x+x0),y:Math.floor(previous.y+y0),w:Math.floor(x1-x0),h:Math.floor(y1-y0)};shiftObjects(previous.x-studio.crop.x,previous.y-studio.crop.y);rebuildImage();setTool('select');commit();fit();toast('已裁切，原圖仍保留在專案中')};
$('resetCrop').onclick=()=>{if(!studio.crop)return;shiftObjects(studio.crop.x,studio.crop.y);studio.crop=null;rebuildImage();commit();fit()};
canvas.addEventListener('pointerdown',e=>{if(!image||e.button!==0)return;e.preventDefault();canvas.focus();const p=point(e);canvas.setPointerCapture(e.pointerId);if(tool==='crop'){drag={kind:'crop',start:p,before:snapshot()};cropPreview={x:p.x,y:p.y,w:0,h:0};return}if(tool==='select'){if(studio.selection.size===1&&selected>=0&&!items[selected].locked){const b=bounds(items[selected]);if(Math.hypot(p.x-b.x-b.w,p.y-b.y-b.h)<(e.pointerType==='touch'?24:14)/zoom){drag={kind:'resize',start:p,original:clone(items[selected]),before:snapshot()};return}}let i=items.findLastIndex(o=>o.type==='mask'&&!o.locked&&hit(o,p));if(i<0)i=items.findLastIndex(o=>!o.locked&&hit(o,p));if(e.shiftKey){const set=new Set(studio.selection);set.has(i)?set.delete(i):i>=0&&set.add(i);setSelection([...set]);return}if(i<0){setSelection([]);return}if(!studio.selection.has(i))setSelection([i]);selected=i;drag={kind:'move',start:p,before:snapshot(),originals:[...studio.selection].filter(j=>!items[j].locked).map(j=>({index:j,item:clone(items[j])}))};syncSelected();render();return}const before=snapshot(),o={id:uid(),type:tool,x:p.x,y:p.y,w:0,h:0,color:$('color').value,width:+$('width').value,size:+$('size').value,locked:false};if(['text','step'].includes(tool)){o.text=$('textInput').value.trim();if(!o.text){toast('請先輸入說明文字');return}}if(['number','step'].includes(tool)){o.n=Math.min(999,Math.max(1,parseInt($('nextNumber').value)||1));$('nextNumber').value=Math.min(999,o.n+1)}if(tool==='step'){o.w=Math.max(160,Math.min(+$('stepWidth').value,canvas.width));const b=bounds(o);o.x=Math.max(0,Math.min(o.x,canvas.width-b.w));o.y=Math.max(0,Math.min(o.y,canvas.height-b.h))}if(tool==='magnify'){o.sx=p.x;o.sy=p.y;o.sw=1;o.sh=1;o.factor=+$('magnifyScale').value}items.push(o);selected=items.length-1;studio.selection=new Set([selected]);if(['text','number','step'].includes(tool)){commit();return}drag={kind:'draw',start:p,before};update();render()});
canvas.addEventListener('pointermove',e=>{if(!drag)return;const p=point(e);if(drag.kind==='crop'){cropPreview={x:Math.min(p.x,drag.start.x),y:Math.min(p.y,drag.start.y),w:Math.abs(p.x-drag.start.x),h:Math.abs(p.y-drag.start.y)};render();return}const o=items[selected];if(!o)return;if(drag.kind==='draw'){o.w=p.x-drag.start.x;o.h=p.y-drag.start.y;if(o.type==='magnify'){const b=bounds(o);o.sx=b.x;o.sy=b.y;o.sw=Math.max(1,b.w);o.sh=Math.max(1,b.h)}}else if(drag.kind==='move'){const dx=p.x-drag.start.x,dy=p.y-drag.start.y;drag.originals.forEach(({index,item})=>{items[index].x=item.x+dx;items[index].y=item.y+dy})}else if(drag.kind==='resize'){const original=drag.original,b=bounds(original);if(['text','number'].includes(o.type)){o.size=Math.max(16,Math.min(160,Math.round(original.size*Math.max(.25,(p.x-b.x)/Math.max(1,b.w)))));$('size').value=o.size}else if(o.type==='step'){o.w=Math.max(160,Math.min(1600,p.x-b.x));$('stepWidth').value=o.w}else if(o.type==='magnify'){o.w=Math.max(20,p.x-b.x);o.h=o.w*o.sh/o.sw}else if(o.type==='arrow'){o.w=original.w+p.x-drag.start.x;o.h=original.h+p.y-drag.start.y}else{o.x=b.x;o.y=b.y;o.w=Math.max(4,p.x-b.x);o.h=Math.max(4,p.y-b.y)}}render()});
function endPointer(){if(!drag)return;const d=drag;drag=null;if(d.kind==='crop'){const b=cropPreview;cropPreview=null;if(b)applyCrop(b);render();return}if(d.kind==='draw'){const o=items[selected];if(Math.hypot(o.w,o.h)<5||(o.type!=='arrow'&&(Math.abs(o.w)<3||Math.abs(o.h)<3))){items.splice(selected,1);selected=-1;studio.selection.clear()}else if(o.type==='magnify'){const b=bounds(o);o.sx=b.x;o.sy=b.y;o.sw=b.w;o.sh=b.h;o.w=Math.min(canvas.width,b.w*o.factor);o.h=o.w*b.h/b.w;o.x=Math.max(0,Math.min(canvas.width-o.w,b.x+b.w+24));o.y=Math.max(0,Math.min(canvas.height-o.h,b.y))}}commit()}
canvas.addEventListener('pointerup',endPointer);canvas.addEventListener('lostpointercapture',endPointer);canvas.addEventListener('pointercancel',()=>{if(drag){const before=drag.before;drag=null;cropPreview=null;restore(before)}});
canvas.addEventListener('dblclick',e=>{if(tool!=='select')return;const i=items.findLastIndex(o=>!o.locked&&hit(o,point(e)));if(i>=0&&['text','step'].includes(items[i].type)){setSelection([i]);$('textInput').focus();$('textInput').select()}});
changeStyle=function(prop,value){[...studio.selection].forEach(i=>{if(items[i]&&!items[i].locked)items[i][prop]=value});render();update()};
removeSelected=function(){const ids=new Set([...studio.selection].filter(i=>!items[i]?.locked));if(!ids.size)return;items=items.filter((_,i)=>!ids.has(i));selected=-1;studio.selection.clear();commit()};
$('delete').onclick=removeSelected;
$('selectAll').onclick=()=>setSelection(items.map((_,i)=>i));$('clearSelection').onclick=()=>setSelection([]);
$('duplicate').onclick=()=>{const copies=[...studio.selection].map(i=>({...clone(items[i]),id:uid(),x:items[i].x+24,y:items[i].y+24,locked:false}));const start=items.length;items.push(...copies);setSelection(copies.map((_,i)=>start+i));commit()};
$('lockItems').onclick=()=>{const ids=[...studio.selection],lock=ids.some(i=>!items[i].locked);ids.forEach(i=>items[i].locked=lock);commit();if(selected>=0)syncSelected()};
$('alignItems').onclick=()=>{const ids=[...studio.selection].filter(i=>!items[i].locked);if(ids.length<2)return;const bs=ids.map(i=>bounds(items[i])),left=Math.min(...bs.map(b=>b.x)),right=Math.max(...bs.map(b=>b.x+b.w)),top=Math.min(...bs.map(b=>b.y)),bottom=Math.max(...bs.map(b=>b.y+b.h)),mode=$('alignMode').value;if(mode==='distribute'){if(ids.length<3){toast('等距排列需要至少 3 個未鎖定標註');return}const sorted=ids.sort((a,b)=>bounds(items[a]).y-bounds(items[b]).y);const gap=(bottom-top-sorted.reduce((sum,i)=>sum+bounds(items[i]).h,0))/(sorted.length-1);let y=top;sorted.forEach(i=>{const b=bounds(items[i]);items[i].y+=y-b.y;y+=b.h+gap})}else ids.forEach((i,j)=>{const b=bs[j];if(mode==='left')items[i].x+=left-b.x;if(mode==='right')items[i].x+=right-b.x-b.w;if(mode==='center')items[i].x+=(left+right-b.w)/2-b.x;if(mode==='top')items[i].y+=top-b.y;if(mode==='bottom')items[i].y+=bottom-b.y-b.h;if(mode==='middle')items[i].y+=(top+bottom-b.h)/2-b.y});commit()};
$('magnifyScale').onchange=()=>{for(const i of studio.selection){const o=items[i];if(o.type==='magnify'&&!o.locked){o.factor=+$('magnifyScale').value;o.w=o.sw*o.factor;o.h=o.sh*o.factor}}commit()};
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||e.target.isContentEditable||document.querySelector('dialog[open]'))return;const key=e.key.toLowerCase(),mod=e.ctrlKey||e.metaKey;if(mod&&key==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if(mod&&key==='y'){e.preventDefault();redo();return}if(mod&&key==='d'){e.preventDefault();$('duplicate').click();return}if(mod&&key==='a'){e.preventDefault();$('selectAll').click();return}if(mod||e.altKey)return;if(key==='delete'||key==='backspace'){e.preventDefault();removeSelected();return}if(key==='escape'){setTool('select');return}if(['arrowleft','arrowright','arrowup','arrowdown'].includes(key)&&studio.selection.size){e.preventDefault();const amount=e.shiftKey?10:1;for(const i of studio.selection)if(!items[i].locked){items[i].x+=(key==='arrowleft'?-amount:key==='arrowright'?amount:0);items[i].y+=(key==='arrowup'?-amount:key==='arrowdown'?amount:0)}commit();return}const keys={v:'select',r:'rect',a:'arrow',n:'number',t:'text',m:'mosaic',s:'step',b:'mask',h:'highlight',c:'crop',z:'magnify'};if(keys[key])setTool(keys[key])});
$('applyTemplate').onclick=()=>{if(!image)return;const mode=$('template').value;if(mode==='free'){toast('自由排版：可直接拖曳標註');return}const steps=items.filter(o=>o.type==='step'&&!o.locked);if(!steps.length){toast('請先加入步驟說明框');return}try{const baseImage=croppedBase(sourceImage,studio.crop),next={...margins};const width=mode==='right'?Math.min(600,Math.max(320,Math.round(baseImage.width*.38))):Math.min(1400,baseImage.width);const proposed=steps.map(o=>({...clone(o),w:width,size:Math.min(o.size,36)}));const total=proposed.reduce((sum,o)=>sum+stepLayout(o).h+24,24);if(total>2000)throw Error('步驟較多，請拆成多頁後套用版型');if(mode==='right'){next.right=Math.max(next.right,width+48);next.bottom=Math.max(next.bottom,Math.ceil(total-baseImage.height))}else next.bottom=Math.max(next.bottom,Math.ceil(total));if(Object.values(next).some(v=>v>2000))throw Error('所需留白過大，請減少本頁步驟');applyCanvasMargins(next,false);let y=mode==='right'?margins.top+24:margins.top+baseImage.height+24;steps.forEach((o,i)=>{o.w=proposed[i].w;o.size=proposed[i].size;o.x=mode==='right'?margins.left+baseImage.width+24:margins.left+Math.max(0,(baseImage.width-width)/2);o.y=y;y+=stepLayout(o).h+24});commit();fit()}catch(e){toast(e.message)}};
const presets={red:{color:'#f43f5e',size:36,width:6},blue:{color:'#2563eb',size:32,width:4},green:{color:'#15803d',size:32,width:4}};
