function pageJSON(p){return{format:'screenshot-studio',version:1,filename:p.name,title:p.title,image:p.encoded,margins:clone(p.margins),items:clone(p.items),crop:p.crop?clone(p.crop):null,nextNumber:p.nextNumber}}
projectData=function(){capturePage();return{format:'screenshot-studio',version:2,autoNumber:studio.autoNumber,active:studio.active,pages:studio.pages.map(pageJSON)}};
function validateExtra(p){base.validateProject({...p,version:1});if(p.title!==undefined&&(typeof p.title!=='string'||p.title.length>300))throw Error('頁面標題不正確');if(p.crop&&(!['x','y','w','h'].every(k=>Number.isInteger(p.crop[k])&&p.crop[k]>=0)||p.crop.w<1||p.crop.h<1))throw Error('裁切資料不正確');for(const o of p.items){if(o.locked!==undefined&&typeof o.locked!=='boolean')throw Error('鎖定資料不正確');if(o.type==='magnify'&&(!['sx','sy','sw','sh','factor'].every(k=>Number.isFinite(o[k])&&Math.abs(o[k])<=64000)||o.sw<=0||o.sh<=0||o.factor<1||o.factor>4))throw Error('放大框資料不正確')}}
async function decodeProject(data){if(!data||data.format!=='screenshot-studio'||![1,2].includes(data.version))throw Error('這不是支援的教學截圖專案');const records=data.version===1?[data]:data.pages;if(!Array.isArray(records)||records.length>30)throw Error('專案頁數不正確');const loaded=[];let pixels=0;for(const p of records){validateExtra(p);const img=new Image();img.src=p.image;await img.decode();pixels+=img.width*img.height;if(img.width>16000||img.height>16000||img.width*img.height>32000000||pixels>100000000)throw Error('專案圖片尺寸過大');if(p.crop&&(p.crop.x+p.crop.w>img.width||p.crop.y+p.crop.h>img.height))throw Error('裁切範圍超出原圖');paddedImage(croppedBase(img,p.crop),p.margins);const page={id:uid(),source:img,encoded:p.image,name:p.filename,title:p.title??p.filename,items:p.items.map(o=>({...o,id:o.id||uid()})),margins:clone(p.margins),crop:p.crop?clone(p.crop):null,nextNumber:Number.isInteger(p.nextNumber)?p.nextNumber:1,history:[],historyIndex:0};page.history=[JSON.stringify({items:page.items,margins:page.margins,crop:page.crop})];loaded.push(page)}return{pages:loaded,active:Math.max(0,Math.min(loaded.length-1,data.active||0)),autoNumber:data.version===1?false:data.autoNumber!==false}}
function installDocument(doc){studio.restoring=true;studio.pages=doc.pages;studio.active=-1;studio.autoNumber=doc.autoNumber;if(doc.pages.length)activatePage(doc.active,false);else{image=sourceImage=null;items=[];selected=-1;studio.selection.clear();$('empty').hidden=false;$('canvasWrap').hidden=true;update()}studio.revision++;studio.restoring=false}
loadProject=async function(file){if(!file)return;try{if(file.size>150*1024*1024)throw Error('專案超過 150 MB');const doc=await decodeProject(JSON.parse(await file.text()));if(studio.pages.length&&!confirm('開啟專案會取代整份教學，請先儲存目前專案。'))return;installDocument(doc);scheduleDraft();toast('已開啟 '+doc.pages.length+' 頁教學，標註仍可編輯')}catch(e){toast(e instanceof SyntaxError?'無法讀取專案 JSON':e.message)}};
$('saveProject').onclick=()=>{try{downloadBlob(new Blob([JSON.stringify(projectData())],{type:'application/json'}),(filename||'教學')+'.screenshot.json');toast('已下載完整多頁專案')}catch(e){toast('無法儲存專案：'+e.message)}};
let draftTimer=null,draftPending=null,draftDirty=false,draftChain=Promise.resolve();
function draftDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open('screenshot-studio-drafts',1);request.onupgradeneeded=()=>request.result.createObjectStore('drafts');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function draftStore(mode,value){const db=await draftDB();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('drafts',mode==='read'?'readonly':'readwrite'),store=tx.objectStore('drafts');const req=mode==='read'?store.get('latest'):mode==='delete'?store.delete('latest'):store.put(value,'latest');let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('儲存已取消'))})}finally{db.close()}}
function scheduleDraft(){if(studio.restoring)return;draftDirty=true;$('draftStatus').textContent=draftPending?'請先恢復或捨棄舊草稿':'尚未儲存…';clearTimeout(draftTimer);if(!draftPending)draftTimer=setTimeout(flushDraft,500)}
function flushDraft(){clearTimeout(draftTimer);if(!draftDirty||draftPending)return draftChain;const payload={savedAt:Date.now(),document:projectData()};draftDirty=false;draftChain=draftChain.catch(()=>{}).then(()=>draftStore('write',payload)).then(()=>{$('draftStatus').textContent=draftDirty?'尚未儲存…':'草稿已自動儲存 · '+new Date(payload.savedAt).toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'})}).catch(()=>{draftDirty=true;$('draftStatus').textContent='草稿儲存失敗，請下載專案備份'});return draftChain}
$('restoreDraft').onclick=async()=>{if(!draftPending)return;try{const doc=await decodeProject(draftPending.document);if(studio.pages.length&&!confirm('恢復草稿會取代目前內容。'))return;installDocument(doc);draftPending=null;$('draftBanner').hidden=true;scheduleDraft();toast('已恢復上次編輯的教學')}catch(e){toast('草稿無法恢復：'+e.message)}};
$('discardDraft').onclick=async()=>{if(!confirm('確定捨棄上次草稿？'))return;try{await draftStore('delete');draftPending=null;$('draftBanner').hidden=true;scheduleDraft()}catch{toast('無法刪除草稿')}};
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flushDraft()});
window.addEventListener('pagehide',flushDraft);
window.addEventListener('beforeunload',e=>{if(draftDirty&&studio.pages.length){flushDraft();e.preventDefault();e.returnValue=''}});
draftStore('read').then(data=>{if(data?.document?.pages?.length){draftPending=data;$('draftBanner').hidden=false;$('draftStatus').textContent='找到可恢復的草稿'}}).catch(()=>{$('draftStatus').textContent='此瀏覽器無法自動儲存，請下載專案'});
const scripts=new Map();
