function pageCanvas(p){const saved={image,items};try{image=paddedImage(croppedBase(p.source,p.crop),p.margins);items=p.items;const c=document.createElement('canvas');c.width=image.width;c.height=image.height;const g=c.getContext('2d');g.drawImage(image,0,0);paintAnnotations(g);return c}finally{image=saved.image;items=saved.items}}
function titleCanvas(title,w=1200){const c=document.createElement('canvas');c.width=w;c.height=80;const g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,w,80);g.fillStyle='#172033';let size=32;do{g.font='700 '+size+'px "Microsoft JhengHei",sans-serif';if(g.measureText(title).width<=w-48)break;size--}while(size>14);g.textBaseline='middle';g.fillText(title,24,40,w-48);return c}
