$('downloadLong').onclick=async()=>{try{capturePage();const width=Number($('bookWidth').value),gap=Number($('bookGap').value);if(!Number.isInteger(width)||width<200||width>4000||!Number.isInteger(gap)||gap<0||gap>500)throw Error('寬度需為 200–4000，間距需為 0–500');const dims=studio.pages.map(p=>{const cropped=p.crop||{w:p.source.width,h:p.source.height};const w=cropped.w+p.margins.left+p.margins.right,h=cropped.h+p.margins.top+p.margins.bottom;return{w,h,scale:Math.min(1,width/w)}});const height=dims.reduce((sum,d)=>sum+Math.round(d.h*d.scale)+64,0)+gap*Math.max(0,dims.length-1);if(height>16000||width*height>32000000)throw Error('長圖過大，請縮小寬度，或改用分頁 PDF');const out=document.createElement('canvas');out.width=width;out.height=height;const g=out.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,width,height);let y=0;studio.pages.forEach((p,i)=>{const c=pageCanvas(p),d=dims[i],w=Math.round(d.w*d.scale),h=Math.round(d.h*d.scale);g.drawImage(titleCanvas((i+1)+'. '+p.title),0,y,width,64);y+=64;g.drawImage(c,(width-w)/2,y,w,h);y+=h+gap});downloadBlob(await canvasBlob(out),'教學長圖.png');$('bookStatus').textContent='長圖已下載，原始多頁專案仍可編輯'}catch(e){$('bookStatus').textContent=e.message}};
async function buildPDF(){capturePage();const exportPages=studio.pages.map(p=>({...p,items:clone(p.items),margins:{...p.margins},crop:p.crop?{...p.crop}:null}));await loadScript('vendor/pdf-lib.min.js');const pdf=await PDFLib.PDFDocument.create(),font=await pdf.embedFont(PDFLib.StandardFonts.Helvetica);let sheet=0;for(let i=0;i<exportPages.length;i++){const p=exportPages[i],c=pageCanvas(p),ratio=523/c.width,slice=Math.max(1,Math.floor(704/ratio));const title=await pdf.embedPng(await (await canvasBlob(titleCanvas((i+1)+'. '+p.title))).arrayBuffer());for(let y=0;y<c.height;y+=slice){const height=Math.min(slice,c.height-y),tile=document.createElement('canvas');tile.width=c.width;tile.height=height;tile.getContext('2d').drawImage(c,0,y,c.width,height,0,0,c.width,height);const asset=await pdf.embedPng(await (await canvasBlob(tile)).arrayBuffer());const page=pdf.addPage([595.28,841.89]);page.drawImage(title,{x:36,y:766,width:523,height:35});page.drawImage(asset,{x:36,y:752-height*ratio,width:523,height:height*ratio});page.drawText(String(++sheet),{x:288,y:20,size:10,font,color:PDFLib.rgb(.4,.45,.5)});tile.width=tile.height=1}$('bookStatus').textContent='正在匯出 '+(i+1)+' / '+exportPages.length+' 頁…';await new Promise(r=>setTimeout(r,0));c.width=c.height=1}return pdf.save()}
$('downloadPDF').onclick=async()=>{if(studio.busy)return;studio.busy=true;$('downloadPDF').disabled=true;try{$('bookStatus').textContent='正在製作 PDF…';const bytes=await buildPDF();downloadBlob(new Blob([bytes],{type:'application/pdf'}),'教學手冊.pdf');$('bookStatus').textContent='PDF 已下載'}catch(e){$('bookStatus').textContent='PDF 匯出失敗：'+e.message}finally{studio.busy=false;$('downloadPDF').disabled=false}};


let ocrWorker=null,ocrRun=0,ocrResult=null;
function ocrWords(tsv){if(typeof tsv!=='string')return[];return tsv.trim().split('\n').slice(1).map(line=>{const a=line.split('\t');return{level:+a[0],group:a.slice(1,5).join(':'),x:+a[6],y:+a[7],w:+a[8],h:+a[9],confidence:+a[10],text:a.slice(11).join('\t')}}).filter(w=>w.level===5&&w.text.trim()&&[w.x,w.y,w.w,w.h].every(Number.isFinite))}
