$('ocrUseText').onclick=()=>{const text=$('ocrText').value.trim();if(!text)return;setTool('text');$('textInput').value=text;$('ocrDialog').close();toast('已填入說明文字，點一下圖片即可放置')};
$('ocrCopy').onclick=async()=>{try{await navigator.clipboard.writeText($('ocrText').value);$('ocrStatus').textContent='文字已複製'}catch{$('ocrStatus').textContent='無法複製，請手動選取文字後複製'}};
$('ocrApply').onclick=()=>{if(!ocrResult||currentPage()?.id!==ocrResult.pageId||studio.revision!==ocrResult.revision){$('ocrStatus').textContent='頁面已改變，請關閉後重新辨識';return}const choices=[...$('ocrCandidates').querySelectorAll('input:checked')].map(n=>ocrResult.candidates[+n.value]);choices.forEach(c=>items.push({id:uid(),type:'mask',x:Math.max(0,Math.floor(c.x)-3),y:Math.max(0,Math.floor(c.y)-3),w:Math.ceil(c.w)+6,h:Math.ceil(c.h)+6,color:'#172033',width:4,size:32,locked:false}));if(choices.length){setSelection([]);commit();$('ocrDialog').close();toast('已遮蔽 '+choices.length+' 個勾選項目，請檢查效果')}};
update();


for(const id of ['textInput','color','width','size','stepWidth'])$(id).addEventListener('input',()=>{if(image){studio.revision++;scheduleDraft()}});

const originalRenderMerge=renderMerge;renderMerge=function(){originalRenderMerge();$('mergeSummary').textContent=mergeBusy?'正在讀取圖片…':mergeImages.length+' 張將加入為獨立頁面';$('buildMerge').disabled=mergeBusy||mergeImages.length<2};
